package com.bank.treasury;

import java.util.logging.Logger;

public class VanLoader {

    private static final Logger log = Logger.getLogger(VanLoader.class.getName());

    public int maxValue(int[] weights, int[] values, int capacity) {
        int[] dp = new int[capacity + 1];
        for (int i = 0; i < weights.length; i++) {
            for (int c = capacity; c >= weights[i]; c--) {  // DOWNWARD ⇒ each item once
                dp[c] = Math.max(dp[c], dp[c - weights[i]] + values[i]);
            }
        }
        int result = dp[capacity];
        log.info(() -> "Best value for capacity " + capacity + " = " + result);
        return result;
    }
}
