package com.bank.treasury;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class KnapsackDemo {

    private static final Logger log = Logger.getLogger(KnapsackDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Treasury Van Loader (0/1 Knapsack)");
        VanLoader loader = new VanLoader();
        int[] weights = {1, 3, 4, 5};
        int[] values  = {1, 4, 5, 7};
        log.info("capacity 7 → " + loader.maxValue(weights, values, 7)); // 9 (items 3+4)
    }
}
